    ("भारत में पहली यात्री रेलगाड़ी 16 अप्रैल 1853 को किन दो शहरों के मध्य चली थी?", ["मुंबई से ठाणे (34 किमी)", "कोलकाता से हुगली", "दिल्ली से आगरा", "मद्रास से अरकोणम"], "A", "लॉर्ड डलहौजी के काल में बोरीबंदर (मुंबई) से ठाणे के बीच पहली रेल चली थी।", "Maharashtra NMMS 2023"),
    ("1905 में बंगाल का विभाजन (Partition of Bengal) किस वायसराय ने किया था?", ["लॉर्ड डलहौजी", "लॉर्ड कर्जन", "लॉर्ड माउंटबेटन", "लॉर्ड कैनिंग"], "B", "लॉर्ड कर्जन ने फूट डालो और राज करो की नीति के तहत 1905 में बंगाल का विभाजन किया।", "All India NMMS 2024"),
    ("गांधीजी ने दक्षिण अफ्रीका से लौटकर भारत में अपना पहला सफल सत्याग्रह 1917 में कहाँ किया?", ["खेड़ा (गुजरात)", "चंपारण (बिहार)", "अहमदाबाद", "दांडी"], "B", "बिहार के चंपारण में राजकुमार शुक्ल के बुलावे पर नील की तीनकठिया प्रथा के विरोध में सत्याग्रह किया।", "Bihar NMMS 2025"),
    ("जलियांवाला बाग का नृशंस हत्याकांड पंजाब के अमृतसर में किस तिथि को हुआ था?", ["13 अप्रैल 1919 (बैसाखी)", "10 मई 1857", "1 अगस्त 1920", "5 फरवरी 1922"], "A", "रॉलेट एक्ट के विरोध में एकत्र निहत्थी भीड़ पर जनरल डायर ने अंधाधुंध गोलियां चलवाईं।", "Punjab NMMS 2023"),
    ("जलियांवाला बाग हत्याकांड के विरोध में किसने अंग्रेजों को 'नाइटहुड' (सर) की उपाधि लौटाई?", ["महात्मा गांधी", "रवींद्रनाथ टैगोर", "सुभाष चंद्र बोस", "जवाहरलाल नेहरू"], "B", "गुरुदेव रवींद्रनाथ टैगोर ने ब्रिटिश सरकार को अपनी नाइटहुड की उपाधि वापस कर दी।", "UP NMMS 2023"),
    ("5 फरवरी 1922 को 'चौरी-चौरा कांड' उत्तर प्रदेश के किस जिले में घटित हुआ था?", ["वाराणसी", "गोरखपुर", "झांसी", "मेरठ"], "B", "गोरखपुर के चौरी-चौरा थाने में भीड़ द्वारा आग लगाने पर गांधीजी ने असहयोग आंदोलन स्थगित किया।", "UP NMMS 2024"),
    ("1928 में भारत आए 'साइमन कमीशन' का देश भर में विरोध क्यों हुआ था?", ["इसमें कोई भारतीय सदस्य नहीं था", "यह बहुत देर से आया", "इसने कर बढ़ा दिए", "यह केवल सेना के लिए था"], "A", "साइमन कमीशन के सभी 7 सदस्य अंग्रेज (श्वेत) थे, इसलिए 'साइमन गो बैक' के नारे लगे।", "All India NMMS 2023"),
    ("साइमन कमीशन के विरोध प्रदर्शन में लाठीचार्ज से किस महान नेता का बलिदान हुआ था?", ["भगत सिंह", "लाला लाजपत राय", "बाल गंगाधर तिलक", "बिपिन चंद्र पाल"], "B", "लाला लाजपत राय ने कहा था: 'मेरे सिर पर पड़ी लाठी की हर चोट ब्रिटिश साम्राज्य के ताबूत की कील बनेगी।' ", "Punjab NMMS 2022"),
    ("1929 के ऐतिहासिक लाहौर कांग्रेस अधिवेशन में 'पूर्ण स्वराज' का प्रस्ताव किसने पारित कराया?", ["महात्मा गांधी", "पं. जवाहरलाल नेहरू", "सुभाष चंद्र बोस", "सरदार पटेल"], "B", "नेहरू की अध्यक्षता में रावी नदी तट पर 26 जनवरी 1930 को प्रथम स्वतंत्रता दिवस मनाने का निर्णय हुआ।", "Bihar NMMS 2023"),
    ("गांधीजी ने 'नमक कानून' तोड़ने के लिए ऐतिहासिक दांडी मार्च कब शुरू किया था?", ["12 मार्च 1930", "6 अप्रैल 1930", "1 अगस्त 1920", "8 अगस्त 1942"], "A", "12 मार्च 1930 को साबरमती से 78 अनुयायियों संग चलकर 6 अप्रैल को दांडी में नमक बनाया।", "Gujarat NMMS 2023"),
    ("'करो या मरो' (Do or Die) का अमर नारा गांधीजी ने किस जन-आंदोलन के दौरान दिया था?", ["असहयोग आंदोलन (1920)", "सविनय अवज्ञा आंदोलन (1930)", "भारत छोड़ो आंदोलन (8 अगस्त 1942)", "चंपारण सत्याग्रह"], "C", "8 अगस्त 1942 को बंबई के ग्वालिया टैंक मैदान से भारत छोड़ो आंदोलन शुरू करते हुए नारा दिया।", "MP NMMS 2024"),
    ("'तुम मुझे खून दो, मैं तुम्हें आजादी दूंगा' और 'जय हिंद' का नारा किसने दिया था?", ["भगत सिंह", "नेताजी सुभाष चंद्र बोस", "चंद्रशेखर आजाद", "रामप्रसाद बिस्मिल"], "B", "आजाद हिंद फौज (INA) के सर्वोच्च सेनापति सुभाष चंद्र बोस ने देशवासियों का आह्वान किया।", "All India NMMS 2024"),
    ("सुभाष चंद्र बोस ने 1939 में कांग्रेस अध्यक्ष पद छोड़ने के बाद किस नए दल का गठन किया?", ["आजाद हिंद फौज", "फॉरवर्ड ब्लॉक (Forward Bloc)", "स्वराज पार्टी", "गदर पार्टी"], "B", "मई 1939 में नेताजी ने क्रांतिकारी राष्ट्रवाद हेतु 'फॉरवर्ड ब्लॉक' की स्थापना की।", "West Bengal NMMS 2023"),
    ("भारत के 'लौह पुरुष' (Iron Man of India) और देशी रियासतों के एकीकरणकर्ता कौन थे?", ["जवाहरलाल नेहरू", "सरदार वल्लभभाई पटेल", "डॉ. राजेंद्र प्रसाद", "लाल बहादुर शास्त्री"], "B", "सरदार पटेल ने 562 से अधिक देशी रियासतों का भारत संघ में विलय कराकर अखंड भारत बनाया।", "Gujarat NMMS 2024"),
    # Civics & Constitution Advanced
    ("भारत में पंचायती राज व्यवस्था का शुभारंभ 2 अक्टूबर 1959 को किस राज्य में हुआ था?", ["उत्तर प्रदेश", "राजस्थान (नागौर जिला)", "बिहार", "गुजरात"], "B", "पं. जवाहरलाल नेहरू ने 2 अक्टूबर 1959 को राजस्थान के नागौर में पंचायती राज शुरू किया।", "Rajasthan NMMS 2024"),
    ("पंचायती राज व्यवस्था को संवैधानिक दर्जा किस संविधान संशोधन द्वारा प्रदान किया गया?", ["42वां संशोधन", "44वां संशोधन", "73वां संविधान संशोधन (1992)", "86वां संशोधन"], "C", "73वें संशोधन द्वारा संविधान में 11वीं अनुसूची जोड़कर 29 विषय पंचायतों को दिए गए।", "All India NMMS 2024"),
    ("त्रिस्तरीय पंचायती राज प्रणाली की सिफारिश किस ऐतिहासिक समिति ने की थी?", ["बलवंत राय मेहता समिति (1957)", "अशोक मेहता समिति", "सरकारिया आयोग", "कोठारी आयोग"], "A", "बलवंत राय मेहता समिति ने ग्राम, ब्लॉक और जिला स्तर पर त्रिस्तरीय ढांचे की सिफारिश की।", "UP NMMS 2023"),
    ("ग्राम पंचायत का चुनाव लड़ने हेतु उम्मीदवार की न्यूनतम आयु सीमा कितनी होनी चाहिए?", ["18 वर्ष", "21 वर्ष", "25 वर्ष", "30 वर्ष"], "B", "वोट देने की आयु 18 वर्ष है, परंतु पंचायत या नगर निकाय चुनाव लड़ने की आयु 21 वर्ष है।", "Bihar NMMS 2023"),
    ("संसद के उच्च सदन 'राज्यसभा' के सदस्यों का कार्यकाल कितने वर्ष का होता है?", ["5 वर्ष", "6 वर्ष", "4 वर्ष", "आजीवन"], "B", "राज्यसभा एक स्थायी सदन है जो कभी भंग नहीं होता; सदस्यों का कार्यकाल 6 वर्ष होता है।", "MP NMMS 2024"),
    ("राज्यसभा के पदेन सभापति (Ex-officio Chairman) कौन होते हैं?", ["प्रधानमंत्री", "भारत के उपराष्ट्रपति", "लोकसभा अध्यक्ष", "मुख्य न्यायाधीश"], "B", "संविधान के अनुच्छेद 64 के अनुसार उपराष्ट्रपति राज्यसभा के पदेन सभापति होते हैं।", "All India NMMS 2025"),
    ("लोकसभा का सदस्य बनने के लिए न्यूनतम आयु सीमा क्या निर्धारित है?", ["18 वर्ष", "21 वर्ष", "25 वर्ष", "30 वर्ष"], "C", "लोकसभा और राज्य विधानसभा चुनाव लड़ने हेतु न्यूनतम आयु 25 वर्ष है।", "UP NMMS 2024"),
    ("संसद के दोनों सदनों की संयुक्त बैठक (Joint Sitting) की अध्यक्षता कौन करता है?", ["राष्ट्रपति", "उपराष्ट्रपति", "लोकसभा अध्यक्ष (Speaker)", "प्रधानमंत्री"], "C", "संयुक्त बैठक राष्ट्रपति द्वारा बुलाई जाती है, परंतु अध्यक्षता लोकसभा अध्यक्ष करते हैं।", "Bihar NMMS 2024"),
    ("भारत के सर्वोच्च न्यायालय (Supreme Court) के मुख्य न्यायाधीश की सेवानिवृत्ति आयु क्या है?", ["60 वर्ष", "62 वर्ष", "65 वर्ष", "68 वर्ष"], "C", "सर्वोच्च न्यायालय के न्यायाधीश 65 वर्ष की आयु तक और उच्च न्यायालय के 62 वर्ष तक पद पर रहते हैं।", "Delhi NMMS 2023"),
    ("भारत के प्रथम मुख्य न्यायाधीश (CJI) कौन थे?", ["एच. जे. कनिया (Harilal Kania)", "एम. पतंजलि शास्त्री", "मेहरचंद महाजन", "बी.के. मुखर्जी"], "A", "न्यायमूर्ति एच. जे. कनिया 26 जनवरी 1950 को स्वतंत्र भारत के पहले मुख्य न्यायाधीश बने।", "Maharashtra NMMS 2023"),
    ("भारतीय संविधान के किस अनुच्छेद में 'स्वतंत्र चुनाव आयोग' (Election Commission) का प्रावधान है?", ["अनुच्छेद 324", "अनुच्छेद 280", "अनुच्छेद 356", "अनुच्छेद 370"], "A", "अनुच्छेद 324 के तहत भारत निर्वाचन आयोग राष्ट्रपति, संसद व विधानसभा चुनाव कराता है।", "UP NMMS 2023"),
    ("प्रत्येक वर्ष 'राष्ट्रीय मतदाता दिवस' (National Voters' Day) किस तिथि को मनाया जाता है?", ["25 जनवरी", "26 जनवरी", "15 अगस्त", "2 अक्टूबर"], "A", "25 जनवरी 1950 को चुनाव आयोग की स्थापना हुई थी, इसलिए 25 जनवरी को मतदाता दिवस मनाते हैं।", "Bihar NMMS 2023"),
    ("भारत में 'सूचना का अधिकार अधिनियम' (RTI Act) किस वर्ष लागू किया गया था?", ["2002 ई.", "2005 ई. (12 अक्टूबर)", "2008 ई.", "2010 ई."], "B", "सरकारी कामकाज में पारदर्शिता लाने हेतु 12 अक्टूबर 2005 को RTI Act लागू हुआ।", "Rajasthan NMMS 2024"),
    ("भारतीय संविधान में मूल कर्तव्यों (Fundamental Duties) की कुल संख्या वर्तमान में कितनी है?", ["10", "11", "12", "7"], "B", "मूल रूप से 10 कर्तव्य जोड़े गए थे; 86वें संशोधन 2002 द्वारा 11वां शिक्षा कर्तव्य जोड़ा गया।", "MP NMMS 2023"),
    ("मौलिक कर्तव्य संविधान के किस भाग एवं अनुच्छेद में शामिल हैं?", ["भाग 3, अनु. 12-35", "भाग 4A, अनुच्छेद 51A", "भाग 4, अनु. 36-51", "भाग 2, अनु. 5-11"], "B", "सरदार स्वर्ण सिंह समिति की सिफारिश पर 42वें संशोधन द्वारा भाग 4A (अनु. 51A) जोड़ा गया।", "All India NMMS 2024"),
    # Physical & World Geography
    ("भारत और पाकिस्तान के बीच की अंतर्राष्ट्रीय सीमा रेखा को क्या कहा जाता है?", ["मैकमोहन रेखा", "रेडक्लिफ रेखा (Radcliffe Line)", "डूरंड रेखा", "49वीं समानांतर"], "B", "1947 में सर सिरिल रेडक्लिफ द्वारा भारत-पाकिस्तान सीमा निर्धारित की गई थी।", "UP NMMS 2024"),
    ("भारत और चीन के मध्य की अंतर्राष्ट्रीय सीमा रेखा का क्या नाम है?", ["रेडक्लिफ रेखा", "मैकमोहन रेखा (McMahon Line)", "डूरंड रेखा", "नियंत्रण रेखा"], "B", "1914 के शिमला समझौते में सर हेनरी मैकमोहन द्वारा भारत-चीन सीमा तय हुई।", "Bihar NMMS 2023"),
